{"command":"cat << 'EOF' > test_tty.go
package main

import (
	"fmt"
	"os"
	"syscall"
	"unsafe"
)

func main() {
	f, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
	if err != nil {
		fmt.Printf("open /dev/tty failed: %v\n", err)
		return
	}
	defer f.Close()
	var termios syscall.Termios
	_, _, sysErr := syscall.Syscall(syscall.SYS_IOCTL, f.Fd(), uintptr(syscall.TCGETS), uintptr(unsafe.Pointer(&termios)))
	if sysErr == 0 {
		fmt.Printf("TCGETS on /dev/tty succeeded: c_lflag = %x\n", termios.Lflag)
	} else {
		fmt.Printf("TCGETS failed: %v\n", sysErr)
	}
}
EOF
go run test_tty.go
rm test_tty.go"}

