{"command":"cat << 'EOF' > test_term.go
package main

import (
	"fmt"
	"os"
	"syscall"
	"unsafe"
)

type winsize struct {
	Row    uint16
	Col    uint16
	Xpixel uint16
	Ypixel uint16
}

func getTermSize(fd uintptr) (int, int, error) {
	var ws winsize
	if _, _, err := syscall.Syscall(syscall.SYS_IOCTL, fd, uintptr(syscall.TIOCGWINSZ), uintptr(unsafe.Pointer(&ws))); err != 0 {
		return 80, 24, err
	}
	return int(ws.Col), int(ws.Row), nil
}

func main() {
	cols, rows, err := getTermSize(uintptr(os.Stdout.Fd()))
	fmt.Printf("cols=%d, rows=%d, err=%v\n", cols, rows, err)
}
EOF
go run test_term.go
rm test_term.go"}

