	WithNth      []FieldRange
	AcceptNth    []FieldRange
	Delimiter    string

	Sort         bool
	Tiebreak     []string
	Tac          bool
	Read0        bool
	Print0       bool
	ANSI         bool
	Sync         bool
	HeaderLines  int
	Header       string
	Footer       string
	Multi        int // 0: disabled, -1: unlimited, >0: max count

	Prompt       string
	Pointer      string
	Marker       string
	Layout       string
	Height       string
	MinHeight    string
	Border       string
	BorderLabel  string

	Preview      string
	PreviewWin   string

	Walker       string
	WalkerRoot   []string
	WalkerSkip   []string

	Bind         map[string]string
}

func defaultOptions() *Options {
	return &Options{
		Extended:   true,
		SmartCase:  true,
		Sort:       true,
		Scheme:     "default",
		Prompt:     "> ",
		Pointer:    ">",
		Marker:     ">",
		Layout:     "default",
		Border:     "rounded",
		Walker:     "file,follow,hidden",
		WalkerRoot: []string{"."},
		WalkerSkip: []string{".git", "node_modules"},
		Tiebreak:   []string{"length"},
		Bind:       make(map[string]string),
	}
}

func tokenizeArgs(str string) []string {
	var args []string
	var buf strings.Builder
	inSingle := false
	inDouble := false
	escaped := false

	for i := 0; i < len(str); i++ {
		ch := str[i]
		if escaped {
			buf.WriteByte(ch)
			escaped = false
			continue
		}
		if ch == '\\' && !inSingle {
			escaped = true
			continue
		}
		if ch == '\'' && !inDouble {
			inSingle = !inSingle
			continue
		}
		if ch == '"' && !inSingle {
			inDouble = !inDouble
			continue
		}
		if (ch == ' ' || ch == '\t' || ch == '\n' || ch == '\r') && !inSingle && !inDouble {
			if buf.Len() > 0 {
				args = append(args, buf.String())
				buf.Reset()
			}
			continue
		}
		buf.WriteByte(ch)
	}
	if buf.Len() > 0 {
		args = append(args, buf.String())
	}
	return args
}

func parseFieldRanges(str string) ([]FieldRange, error) {
	parts := strings.Split(str, ",")
	var res []FieldRange
	for _, p := range parts {
		p = strings.TrimSpace(p)
		if p == ".." || p == "" {
			res = append(res, FieldRange{All: true})
			continue
		}
		if strings.Contains(p, "..") {
			sub := strings.SplitN(p, "..", 2)
			fr := FieldRange{}
			if sub[0] != "" {
				v, err := strconv.Atoi(sub[0])
				if err != nil {
					return nil, fmt.Errorf("invalid range")
				}
				fr.Begin = v
			}
			if sub[1] != "" {
				v, err := strconv.Atoi(sub[1])
				if err != nil {
					return nil, fmt.Errorf("invalid range")
				}
				fr.End = v
			} else {
				fr.End = -999 // end of line
			}
			res = append(res, fr)
		} else {
			v, err := strconv.Atoi(p)
			if err != nil {
				return nil, fmt.Errorf("invalid field number")
			}
			res = append(res, FieldRange{Begin: v, End: v})
		}
