func parseOptions() *Options {
	opts := defaultOptions()

	var allArgs []string

	// 1. FZF_DEFAULT_OPTS_FILE
	if optsFile := os.Getenv("FZF_DEFAULT_OPTS_FILE"); optsFile != "" {
		if content, err := os.ReadFile(optsFile); err == nil {
			allArgs = append(allArgs, tokenizeArgs(string(content))...)
