		os.Exit(2)
	}

	for i := 0; i < len(allArgs); i++ {
		arg := allArgs[i]

		getValue := func(reqMsg string) string {
			if strings.Contains(arg, "=") {
				return arg[strings.Index(arg, "=")+1:]
			}
			if i+1 < len(allArgs) {
				i++
				return allArgs[i]
			}
			fail(reqMsg)
			return ""
		}

		getOptionalValue := func() string {
			if strings.Contains(arg, "=") {
				return arg[strings.Index(arg, "=")+1:]
			}
			if i+1 < len(allArgs) && !strings.HasPrefix(allArgs[i+1], "-") && !strings.HasPrefix(allArgs[i+1], "+") {
				i++
				return allArgs[i]
			}
			return ""
		}

		if arg == "--version" {
			opts.Version = true
		} else if arg == "--help" || arg == "-h" {
			opts.Help = true
		} else if arg == "--man" {
			opts.Man = true
		} else if arg == "--bash" {
			opts.Bash = true
		} else if arg == "--zsh" {
			opts.Zsh = true
		} else if arg == "--fish" {
			opts.Fish = true
		} else if arg == "-e" || arg == "--exact" {
			opts.Exact = true
		} else if arg == "+x" || arg == "--no-extended" {
			opts.Extended = false
		} else if arg == "-x" || arg == "--extended" {
			opts.Extended = true
		} else if arg == "-i" || arg == "--ignore-case" {
			opts.IgnoreCase = true
			opts.NoIgnoreCase = false
		} else if arg == "+i" || arg == "--no-ignore-case" {
			opts.NoIgnoreCase = true
			opts.IgnoreCase = false
		} else if arg == "--smart-case" {
			opts.SmartCase = true
			opts.IgnoreCase = false
			opts.NoIgnoreCase = false
		} else if arg == "--literal" {
			opts.Literal = true
		} else if strings.HasPrefix(arg, "--scheme") {
			val := getValue("scoring scheme required (default|path|history)")
			if val != "default" && val != "path" && val != "history" {
				fail(fmt.Sprintf("invalid scoring scheme: %s (expected: default|path|history)", val))
			}
			opts.Scheme = val
		} else if strings.HasPrefix(arg, "-n") || strings.HasPrefix(arg, "--nth") {
			var val string
			if arg == "-n" || arg == "--nth" {
				val = getValue("nth expression required")
			} else if strings.HasPrefix(arg, "-n") && !strings.HasPrefix(arg, "--") {
				val = arg[2:]
			} else {
				val = getValue("nth expression required")
			}
			fr, err := parseFieldRanges(val)
			if err != nil {
				fail("nth expression required")
			}
			opts.Nth = fr
		} else if strings.HasPrefix(arg, "--with-nth") {
			val := getValue("nth expression required")
			fr, err := parseFieldRanges(val)
			if err != nil {
				fail("nth expression required")
			}
			opts.WithNth = fr
		} else if strings.HasPrefix(arg, "--accept-nth") {
			val := getValue("nth expression required")
			fr, err := parseFieldRanges(val)
			if err != nil {
				fail("nth expression required")
			}
			opts.AcceptNth = fr
		} else if strings.HasPrefix(arg, "-d") || strings.HasPrefix(arg, "--delimiter") {
			var val string
			if arg == "-d" || arg == "--delimiter" {
				val = getValue("delimiter required")
			} else if strings.HasPrefix(arg, "-d") && !strings.HasPrefix(arg, "--") {
				val = arg[2:]
			} else {
				val = getValue("delimiter required")
			}
			opts.Delimiter = val
		} else if arg == "+s" || arg == "--no-sort" {
			opts.Sort = false
		} else if arg == "-s" || arg == "--sort" {
			opts.Sort = true
		} else if strings.HasPrefix(arg, "--tiebreak") {
			val := getValue("sort criterion required")
			parts := strings.Split(val, ",")
			validCriteria := map[string]bool{"length": true, "chunk": true, "pathname": true, "begin": true, "end": true, "index": true}
			for _, p := range parts {
				p = strings.TrimSpace(p)
				if !validCriteria[p] {
					fail(fmt.Sprintf("invalid sort criterion: %s", p))
				}
			}
			opts.Tiebreak = parts
		} else if arg == "--read0" {
			opts.Read0 = true
		} else if arg == "--print0" {
			opts.Print0 = true
		} else if arg == "--ansi" {
			opts.ANSI = true
		} else if arg == "--sync" {
			opts.Sync = true
		} else if strings.HasPrefix(arg, "--style") {
			val := getValue("preset name required: [default|minimal|full[:BORDER_STYLE]]")
			if !strings.HasPrefix(val, "default") && !strings.HasPrefix(val, "minimal") && !strings.HasPrefix(val, "full") {
				fail(fmt.Sprintf("unsupported style preset: %s", val))
			}
		} else if strings.HasPrefix(arg, "--height") {
			opts.Height = getValue("height required: [~]HEIGHT[%]")
		} else if strings.HasPrefix(arg, "--min-height") {
			opts.MinHeight = getValue("minimum height required: HEIGHT[+]")
		} else if strings.HasPrefix(arg, "--margin") {
			getValue("margin required (TRBL / TB,RL / T,RL,B / T,R,B,L)")
		} else if strings.HasPrefix(arg, "--padding") {
			getValue("padding required (TRBL / TB,RL / T,RL,B / T,R,B,L)")
		} else if strings.HasPrefix(arg, "--border") {
			val := getOptionalValue()
			if val == "" {
				opts.Border = "rounded"
			} else {
				validBorders := map[string]bool{"rounded": true, "sharp": true, "bold": true, "block": true, "thinblock": true, "double": true, "horizontal": true, "vertical": true, "top": true, "bottom": true, "left": true, "right": true, "line": true, "none": true}
				if !validBorders[val] {
					fail("invalid border style (expected: rounded|sharp|bold|block|thinblock|double|horizontal|vertical|top|bottom|left|right|none)")
				}
				opts.Border = val
			}
		} else if strings.HasPrefix(arg, "--layout") {
			val := getValue("invalid layout (expected: default / reverse / reverse-list)")
			if val != "default" && val != "reverse" && val != "reverse-list" {
				fail("invalid layout (expected: default / reverse / reverse-list)")
			}
			opts.Layout = val
		} else if strings.HasPrefix(arg, "--info") {
			val := getValue("invalid info style (expected: default|right|hidden|inline[-right][:PREFIX])")
			if !strings.HasPrefix(val, "default") && !strings.HasPrefix(val, "right") && !strings.HasPrefix(val, "hidden") && !strings.HasPrefix(val, "inline") {
				fail("invalid info style (expected: default|right|hidden|inline[-right][:PREFIX])")
			}
		} else if strings.HasPrefix(arg, "-m") || strings.HasPrefix(arg, "--multi") {
			val := getOptionalValue()
			if val == "" {
				opts.Multi = -1
			} else {
				n, err := strconv.Atoi(val)
				if err != nil || n <= 0 {
					opts.Multi = -1
				} else {
					opts.Multi = n
				}
			}
		} else if arg == "+m" || arg == "--no-multi" {
			opts.Multi = 0
		} else if arg == "--tac" {
			opts.Tac = true
		} else if strings.HasPrefix(arg, "-q") || strings.HasPrefix(arg, "--query") {
			var val string
			if arg == "-q" || arg == "--query" {
				val = getValue("query string required")
			} else if strings.HasPrefix(arg, "-q") && !strings.HasPrefix(arg, "--") {
				val = arg[2:]
			} else {
				val = getValue("query string required")
			}
			opts.Query = val
		} else if arg == "-1" || arg == "--select-1" {
			opts.Select1 = true
		} else if arg == "+1" || arg == "--no-select-1" {
			opts.Select1 = false
		} else if arg == "-0" || arg == "--exit-0" {
			opts.Exit0 = true
		} else if arg == "+0" || arg == "--no-exit-0" {
			opts.Exit0 = false
		} else if strings.HasPrefix(arg, "-f") || strings.HasPrefix(arg, "--filter") {
			var val string
			if arg == "-f" || arg == "--filter" {
				val = getValue("query string required")
			} else if strings.HasPrefix(arg, "-f") && !strings.HasPrefix(arg, "--") {
				val = arg[2:]
			} else {
				val = getValue("query string required")
			}
			opts.Filter = &val
		} else if arg == "--print-query" {
			opts.PrintQuery = true
		} else if strings.HasPrefix(arg, "--expect") {
			val := getValue("key names required")
			opts.Expect = strings.Split(val, ",")
		} else if strings.HasPrefix(arg, "--bind") {
			val := getValue("bind expression required")
			opts.Bind[val] = val
		} else if strings.HasPrefix(arg, "--header-lines") {
			val := getValue("number of header lines required")
			n, err := strconv.Atoi(val)
			if err != nil {
				fail("number of header lines required")
			}
			opts.HeaderLines = n
		} else if strings.HasPrefix(arg, "--header") {
			opts.Header = getValue("header string required")
		} else if strings.HasPrefix(arg, "--footer") {
			opts.Footer = getValue("footer string required")
		} else if strings.HasPrefix(arg, "--prompt") {
			opts.Prompt = getValue("prompt string required")
		} else if strings.HasPrefix(arg, "--pointer") {
			opts.Pointer = getValue("pointer string required")
		} else if strings.HasPrefix(arg, "--marker") {
			opts.Marker = getValue("marker string required")
		} else if strings.HasPrefix(arg, "--preview") {
			opts.Preview = getValue("preview command required")
		} else if strings.HasPrefix(arg, "--preview-window") {
			opts.PreviewWin = getValue("preview window layout required: [up|down|left|right][,SIZE[%]][,border-STYLE][,wrap][,cycle][,hidden][,+SCROLL[OFFSETS][/DENOM]][,~HEADER_LINES][,default]")
		} else if strings.HasPrefix(arg, "--walker-root") {
			val := getValue("no directory specified")
			opts.WalkerRoot = strings.Split(val, ",")
		} else if strings.HasPrefix(arg, "--walker-skip") {
			val := getValue("directory names to ignore required")
			opts.WalkerSkip = strings.Split(val, ",")
		} else if strings.HasPrefix(arg, "--walker") {
			opts.Walker = getValue("walker options required [file][,dir][,follow][,hidden]")
		} else if strings.HasPrefix(arg, "--history-size") {
			getValue("history max size required")
		} else if strings.HasPrefix(arg, "--history") {
			getValue("history file path required")
		} else if strings.HasPrefix(arg, "-") || strings.HasPrefix(arg, "+") {
			fail(fmt.Sprintf("unknown option: %s", arg))
		}
	}

	return opts
}
