{"command":"cat << 'EOF' > matcher.go
package main

import (
	"regexp"
	"sort"
	"strings"
	"unicode"
	"unicode/utf8"
)

type MatchResult struct {
	Index   int
	Line    string
	Display string
	Output  string
	Score   int
	Span    int
	Begin   int
	End     int
}

func splitLine(line string, delimiter string) []string {
	if delimiter == "" {
		// AWK-style: whitespace
		return strings.Fields(line)
	}
	re, err := regexp.Compile(delimiter)
	if err != nil {
		return strings.Split(line, delimiter)
	}
	return re.Split(line, -1)
}

func getFieldByRange(fields []string, fr FieldRange) []string {
	n := len(fields)
	if n == 0 {
		return nil
	}
	if fr.All {
		return fields
	}

	normIdx := func(idx int) int {
		if idx > 0 {
			return idx - 1
		} else if idx < 0 {
			return n + idx
		}
		return -1
	}

	begin := normIdx(fr.Begin)
	end := normIdx(fr.End)

	if fr.Begin == 0 {
		begin = 0
	}
	if fr.End == -999 || fr.End == 0 {
		end = n - 1
	}

	if begin < 0 {
		begin = 0
	}
	if end >= n {
		end = n - 1
	}
	if begin > end || begin >= n || end < 0 {
		return nil
	}

	return fields[begin : end+1]
}

func transformLine(line string, delimiter string, nth []FieldRange) string {
	if len(nth) == 0 {
		return line
	}
	fields := splitLine(line, delimiter)
	var res []string
	for _, fr := range nth {
		sub := getFieldByRange(fields, fr)
		res = append(res, sub...)
	}
	sep := delimiter
	if delimiter == "" {
		sep = " "
	}
	return strings.Join(res, sep)
}

func stripANSI(str string) string {
	re := regexp.MustCompile(`\x1b\[[0-9;]*[a-zA-Z]`)
	return re.ReplaceAllString(str, "")
}

type Subterm struct {
	Pattern   string
	Negated   bool
	Prefix    bool
	Suffix    bool
	Exact     bool
	Lower     string
	IsLower   bool
}

func parseSubterm(raw string, exactMode bool) Subterm {
	st := Subterm{}
	if strings.HasPrefix(raw, "!") {
		st.Negated = true
		raw = raw[1:]
	}
	if strings.HasPrefix(raw, "'") {
		st.Exact = true
		raw = raw[1:]
	} else if exactMode {
		st.Exact = true
	}

	if strings.HasPrefix(raw, "^") {
		st.Prefix = true
		raw = raw[1:]
	}
	if strings.HasSuffix(raw, "$") {
		st.Suffix = true
		raw = raw[:len(raw)-1]
	}

	st.Pattern = raw
	st.Lower = strings.ToLower(raw)
	st.IsLower = (st.Pattern == st.Lower)
	return st
}

type Term struct {
	Subterms []Subterm
}

func parseQuery(query string, exactMode bool) []Term {
	rawTerms := strings.Fields(query)
	var terms []Term
	for _, rt := range rawTerms {
		orParts := strings.Split(rt, "|")
		t := Term{}
		for _, op := range orParts {
			if op != "" {
				t.Subterms = append(t.Subterms, parseSubterm(op, exactMode))
			}
		}
		if len(t.Subterms) > 0 {
			terms = append(terms, t)
		}
	}
	return terms
}

func isWordBoundary(str string, idx int) bool {
	if idx <= 0 {
		return true
	}
	prev, _ := utf8.DecodeLastRuneInString(str[:idx])
	curr, _ := utf8.DecodeRuneInString(str[idx:])

	if unicode.IsSpace(prev) || prev == '/' || prev == '_' || prev == '-' || prev == '.' || prev == ':' || prev == '\\' {
		return true
	}
	if unicode.IsLower(prev) && unicode.IsUpper(curr) {
		return true
	}
	return false
}

func matchSubterm(st Subterm, target string, opts *Options) (bool, int, int, int) {
	if st.Pattern == "" {
		return true, 0, 0, 0
	}

	tStr := target
	pStr := st.Pattern

	ignoreCase := opts.IgnoreCase
	if opts.SmartCase && !opts.NoIgnoreCase && !opts.IgnoreCase {
		if st.IsLower {
			ignoreCase = true
		} else {
			ignoreCase = false
		}
	} else if opts.NoIgnoreCase {
		ignoreCase = false
	}

	if ignoreCase {
		tStr = strings.ToLower(tStr)
		pStr = st.Lower
	}

	if st.Prefix {
		if strings.HasPrefix(tStr, pStr) {
			score := 500 - len(target)
			if st.Negated {
				return false, 0, 0, 0
			}
			return true, score, 0, len(st.Pattern)
		}
		if st.Negated {
			return true, 0, 0, 0
		}
		return false, 0, 0, 0
	}

	if st.Suffix {
		if strings.HasSuffix(tStr, pStr) {
			score := 500 - len(target)
			begin := len(target) - len(st.Pattern)
			if st.Negated {
				return false, 0, 0, 0
			}
			return true, score, begin, len(target)
		}
		if st.Negated {
			return true, 0, 0, 0
		}
		return false, 0, 0, 0
	}

	if st.Exact {
		idx := strings.Index(tStr, pStr)
		if idx >= 0 {
			if st.Negated {
				return false, 0, 0, 0
			}
			score := 500 - len(target)
			if isWordBoundary(target, idx) {
				score += 50
			}
			return true, score, idx, idx + len(st.Pattern)
		}
		if st.Negated {
			return true, 0, 0, 0
		}
		return false, 0, 0, 0
	}

	// Fuzzy match
	pRunes := []rune(pStr)
	tRunes := []rune(tStr)

	pIdx := 0
	firstMatch := -1
	lastMatch := -1
	score := 0
	consecutive := 0

	for tIdx, tr := range tRunes {
		if pIdx < len(pRunes) && tr == pRunes[pIdx] {
			if firstMatch < 0 {
				firstMatch = tIdx
			}
			lastMatch = tIdx
			score += 100

			if isWordBoundary(tStr, tIdx) {
				score += 30
			}
			if consecutive > 0 {
				score += 20 * consecutive
			}
			consecutive++
			pIdx++
		} else {
			consecutive = 0
		}
	}

	if pIdx == len(pRunes) {
		if st.Negated {
			return false, 0, 0, 0
		}
		span := lastMatch - firstMatch
		score -= span
		score -= len(target)
		return true, score, firstMatch, lastMatch + 1
	}

	if st.Negated {
		return true, 0, 0, 0
	}
	return false, 0, 0, 0
}

func filterItems(lines []string, opts *Options) []MatchResult {
	query := opts.Query
	if opts.Filter != nil {
		query = *opts.Filter
	}

	var inputLines []string
	if opts.HeaderLines > 0 && opts.HeaderLines < len(lines) {
		inputLines = lines[opts.HeaderLines:]
	} else {
		inputLines = lines
	}

	if opts.Tac {
		reversed := make([]string, len(inputLines))
		for i, l := range inputLines {
			reversed[len(inputLines)-1-i] = l
		}
		inputLines = reversed
	}

	terms := parseQuery(query, opts.Exact)

	var results []MatchResult

	for idx, originalLine := range inputLines {
		line := originalLine
		if opts.ANSI {
			line = stripANSI(line)
		}

		targetStr := line
		if len(opts.Nth) > 0 {
			targetStr = transformLine(line, opts.Delimiter, opts.Nth)
		}

		displayStr := originalLine
		if len(opts.WithNth) > 0 {
			displayStr = transformLine(originalLine, opts.Delimiter, opts.WithNth)
		}

		outputStr := originalLine
		if len(opts.AcceptNth) > 0 {
			outputStr = transformLine(originalLine, opts.Delimiter, opts.AcceptNth)
		}

		totalScore := 0
		totalSpan := 0
		minBegin := 999999
		maxEnd := 0
		matchedAll := true

		for _, term := range terms {
			termMatched := false
			termScore := -999999
			termBegin := 0
			termEnd := 0

			for _, st := range term.Subterms {
				ok, sc, b, e := matchSubterm(st, targetStr, opts)
				if ok {
					termMatched = true
					if sc > termScore {
						termScore = sc
						termBegin = b
						termEnd = e
					}
				}
			}

			if !termMatched {
				matchedAll = false
				break
			}
			totalScore += termScore
			if termBegin < minBegin {
				minBegin = termBegin
			}
			if termEnd > maxEnd {
				maxEnd = termEnd
			}
		}

		if matchedAll {
			totalSpan = maxEnd - minBegin
			results = append(results, MatchResult{
				Index:   idx,
				Line:    originalLine,
				Display: displayStr,
				Output:  outputStr,
				Score:   totalScore,
				Span:    totalSpan,
				Begin:   minBegin,
				End:     maxEnd,
			})
		}
	}

	if opts.Sort && query != "" {
		sort.SliceStable(results, func(i, j int) bool {
			if results[i].Score != results[j].Score {
				return results[i].Score > results[j].Score
			}
			for _, tb := range opts.Tiebreak {
				switch tb {
				case "length":
					if len(results[i].Line) != len(results[j].Line) {
						return len(results[i].Line) < len(results[j].Line)
					}
				case "begin":
					if results[i].Begin != results[j].Begin {
						return results[i].Begin < results[j].Begin
					}
				case "end":
					if results[i].End != results[j].End {
						return results[i].End < results[j].End
					}
				case "index":
					return results[i].Index < results[j].Index
				}
			}
			return results[i].Index < results[j].Index
		})
	}

	return results
}
EOF"}

