		}

		outputStr := originalLine
		if len(opts.AcceptNth) > 0 {
			outputStr = transformLine(originalLine, opts.Delimiter, opts.AcceptNth)
		}

		totalScore := 0
		totalSpan := 0
		minBegin := 999999
		maxEnd := 0
		matchedAll := true

		for _, term := range terms {
			termMatched := false
			termScore := -999999
			termBegin := 0
			termEnd := 0

			for _, st := range term.Subterms {
				ok, sc, b, e := matchSubterm(st, targetStr, opts)
