			totalSpan = maxEnd - minBegin
			results = append(results, MatchResult{
				Index:   idx,
				Line:    originalLine,
				Display: displayStr,
				Output:  outputStr,
				Score:   totalScore,
				Span:    totalSpan,
				Begin:   minBegin,
				End:     maxEnd,
			})
		}
	}

	if opts.Sort && query != "" {
		sort.SliceStable(results, func(i, j int) bool {
			if results[i].Score != results[j].Score {
				return results[i].Score > results[j].Score
			}
			for _, tb := range opts.Tiebreak {
				switch tb {
				case "length":
					if len(results[i].Line) != len(results[j].Line) {
