						return results[i].Begin < results[j].Begin
					}
				case "end":
					if results[i].End != results[j].End {
						return results[i].End < results[j].End
					}
				case "index":
					return results[i].Index < results[j].Index
				}
			}
			return results[i].Index < results[j].Index
		})
	}

	return results
}
