{"command":"cat << 'EOF' > walker.go
package main

import (
	"bufio"
	"io/fs"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
)

func getDefaultInputs(opts *Options) []string {
	defCmd := os.Getenv("FZF_DEFAULT_COMMAND")
	if defCmd != "" {
		cmd := exec.Command("sh", "-c", defCmd)
		out, err := cmd.Output()
		if err == nil {
			lines := strings.Split(string(out), "\n")
			var res []string
			for _, l := range lines {
				if l != "" || len(res) > 0 {
					res = append(res, l)
				}
			}
			if len(res) > 0 && res[len(res)-1] == "" {
				res = res[:len(res)-1]
			}
			return res
		}
	}

	var res []string
	walkerOpts := opts.Walker
	includeFiles := strings.Contains(walkerOpts, "file")
	includeDirs := strings.Contains(walkerOpts, "dir")

	skipDirs := make(map[string]bool)
	for _, s := range opts.WalkerSkip {
		skipDirs[s] = true
	}

	roots := opts.WalkerRoot
	if len(roots) == 0 {
		roots = []string{"."}
	}

	for _, root := range roots {
		filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
			if err != nil {
				return nil
			}
			base := d.Name()
			if d.IsDir() {
				if skipDirs[base] && path != root {
					return filepath.SkipDir
				}
				if includeDirs && path != root {
					res = append(res, path)
				}
			} else {
				if includeFiles {
					res = append(res, path)
				}
			}
			return nil
		})
	}

	return res
}

func readStdinInputs(opts *Options) []string {
	var lines []string
	if opts.Read0 {
		scanner := bufio.NewScanner(os.Stdin)
		scanner.Split(func(data []byte, atEOF bool) (advance int, token []byte, err error) {
			if atEOF && len(data) == 0 {
				return 0, nil, nil
			}
			if i := strings.IndexByte(string(data), 0); i >= 0 {
				return i + 1, data[0:i], nil
			}
			if atEOF {
				return len(data), data, nil
			}
			return 0, nil, nil
		})
		for scanner.Scan() {
			lines = append(lines, scanner.Text())
		}
	} else {
		scanner := bufio.NewScanner(os.Stdin)
		// Increase max token size for long lines
		buf := make([]byte, 64*1024)
		scanner.Buffer(buf, 1024*1024)
		for scanner.Scan() {
			lines = append(lines, scanner.Text())
		}
	}
	return lines
}
EOF"}

