		if visibleRows < 1 {
			visibleRows = 1
		}

		if selectedIdx >= len(results) {
			selectedIdx = len(results) - 1
		}
		if selectedIdx < 0 {
			selectedIdx = 0
		}

		if selectedIdx < scrollOffset {
			scrollOffset = selectedIdx
		} else if selectedIdx >= scrollOffset+visibleRows {
			scrollOffset = selectedIdx - visibleRows + 1
		}

		// Render screen
		var b strings.Builder
		b.WriteString("\033[2J\033[H") // clear screen and move to top-left

		if opts.Layout == "reverse" || opts.Layout == "reverse-list" {
			// Prompt at top
			b.WriteString(fmt.Sprintf("%s%s\r\n", opts.Prompt, query))
			infoStr := fmt.Sprintf("  %d/%d", len(results), len(lines))
			if len(selectedMap) > 0 {
				infoStr += fmt.Sprintf(" (%d)", len(selectedMap))
			}
			b.WriteString(infoStr + "\r\n")

			for i := 0; i < visibleRows; i++ {
				rIdx := scrollOffset + i
				if rIdx < len(results) {
					res := results[rIdx]
					ptr := " "
					if rIdx == selectedIdx {
						ptr = opts.Pointer
					}
					mrk := " "
					if selectedMap[res.Index] {
						mrk = opts.Marker
					}
					lineDisp := res.Display
					if len(lineDisp) > cols-6 {
						lineDisp = lineDisp[:cols-6]
					}
					if rIdx == selectedIdx {
						b.WriteString(fmt.Sprintf("%s%s \033[7m%s\033[0m\r\n", ptr, mrk, lineDisp))
					} else {
						b.WriteString(fmt.Sprintf("%s%s %s\r\n", ptr, mrk, lineDisp))
					}
				} else {
					b.WriteString("\r\n")
				}
			}
		} else {
			// Default layout: items at top, prompt at bottom
			for i := visibleRows - 1; i >= 0; i-- {
				rIdx := scrollOffset + i
				if rIdx < len(results) {
					res := results[rIdx]
					ptr := " "
					if rIdx == selectedIdx {
						ptr = opts.Pointer
					}
					mrk := " "
					if selectedMap[res.Index] {
						mrk = opts.Marker
					}
					lineDisp := res.Display
					if len(lineDisp) > cols-6 {
						lineDisp = lineDisp[:cols-6]
					}
					if rIdx == selectedIdx {
						b.WriteString(fmt.Sprintf("%s%s \033[7m%s\033[0m\r\n", ptr, mrk, lineDisp))
					} else {
						b.WriteString(fmt.Sprintf("%s%s %s\r\n", ptr, mrk, lineDisp))
					}
				} else {
					b.WriteString("\r\n")
				}
			}
			infoStr := fmt.Sprintf("  %d/%d", len(results), len(lines))
			if len(selectedMap) > 0 {
				infoStr += fmt.Sprintf(" (%d)", len(selectedMap))
			}
			b.WriteString(infoStr + "\r\n")
			b.WriteString(fmt.Sprintf("%s%s", opts.Prompt, query))
		}

		tty.WriteString(b.String())

		// Read key
		n, err := tty.Read(readBuf)
		if err != nil && err != io.EOF {
			break
		}
		if n == 0 {
			continue
		}

		keyData := readBuf[:n]

		if n == 1 {
			ch := keyData[0]
			if ch == 13 || ch == 10 { // Enter
				restoreTerm(ttyFd, oldTerm)

				if opts.PrintQuery {
					if opts.Print0 {
						fmt.Print(query + "\x00")
					} else {
						fmt.Println(query)
					}
				}

				if len(opts.Expect) > 0 {
					if opts.Print0 {
						fmt.Print("\x00")
					} else {
						fmt.Println("")
					}
				}

				if len(selectedMap) > 0 {
					for idx, sel := range selectedMap {
						if sel && idx < len(lines) {
							if opts.Print0 {
								fmt.Print(lines[idx] + "\x00")
							} else {
								fmt.Println(lines[idx])
							}
						}
					}
				} else if selectedIdx < len(results) {
					out := results[selectedIdx].Output
					if opts.Print0 {
						fmt.Print(out + "\x00")
					} else {
						fmt.Println(out)
					}
				}
				os.Exit(0)
			} else if ch == 27 { // ESC
				restoreTerm(ttyFd, oldTerm)
				os.Exit(130)
			} else if ch == 3 || ch == 7 || ch == 17 { // Ctrl-C, Ctrl-G, Ctrl-Q
				restoreTerm(ttyFd, oldTerm)
				os.Exit(130)
			} else if ch == 127 || ch == 8 { // Backspace
				qRunes := []rune(query)
				if cursorPos > 0 {
					query = string(qRunes[:cursorPos-1]) + string(qRunes[cursorPos:])
					cursorPos--
					results = filterItems(lines, opts)
					selectedIdx = 0
				}
			} else if ch == 21 { // Ctrl-U
				query = ""
				cursorPos = 0
				results = filterItems(lines, opts)
				selectedIdx = 0
			} else if ch == 1 { // Ctrl-A
				cursorPos = 0
			} else if ch == 5 { // Ctrl-E
				cursorPos = len([]rune(query))
			} else if ch == 14 || ch == 10 { // Ctrl-N / Ctrl-J (Down)
				selectedIdx++
			} else if ch == 16 || ch == 11 { // Ctrl-P / Ctrl-K (Up)
				selectedIdx--
			} else if ch == 9 { // Tab
				if opts.Multi != 0 && selectedIdx < len(results) {
					resIdx := results[selectedIdx].Index
					selectedMap[resIdx] = !selectedMap[resIdx]
					selectedIdx++
				}
			} else if ch >= 32 && ch < 127 { // Printable char
				qRunes := []rune(query)
				query = string(qRunes[:cursorPos]) + string(ch) + string(qRunes[cursorPos:])
				cursorPos++
				opts.Query = query
				results = filterItems(lines, opts)
				selectedIdx = 0
			}
		} else if n >= 3 && keyData[0] == 27 && keyData[1] == '[' {
			switch keyData[2] {
			case 'A': // Up
				selectedIdx--
			case 'B': // Down
				selectedIdx++
			case 'C': // Right
				if cursorPos < len([]rune(query)) {
					cursorPos++
				}
			case 'D': // Left
				if cursorPos > 0 {
					cursorPos--
				}
			case 'H': // Home
				cursorPos = 0
			case 'F': // End
				cursorPos = len([]rune(query))
			case 'Z': // Shift-Tab
				if opts.Multi != 0 && selectedIdx < len(results) {
					resIdx := results[selectedIdx].Index
					selectedMap[resIdx] = !selectedMap[resIdx]
					selectedIdx--
				}
			}
		}
	}
}

func isTerminal(fd uintptr) bool {
	var termios syscall.Termios
	_, _, err := syscall.Syscall(syscall.SYS_IOCTL, fd, uintptr(syscall.TCGETS), uintptr(unsafe.Pointer(&termios)))
	return err == 0
}
EOF"}

